#ifdef GL_ES
precision mediump float;
#endif



//-----------------------------------------------------
// Example quaternion-based rotation in 4D (Spin(4))
// plus inverse stereographic, 4D Menger, etc.
// Then do membership-based raymarch with binary refine.
//-----------------------------------------------------

//----------------------------------------------
// Quaternion Tools
//----------------------------------------------
vec4 quatMul(in vec4 q1, in vec4 q2)
{
    // q1=(w1,x1,y1,z1), q2=(w2,x2,y2,z2)
    float w = q1.x*q2.x - (q1.y*q2.y + q1.z*q2.z + q1.w*q2.w);
    float x = q1.x*q2.y + q2.x*q1.y + (q1.z*q2.w - q1.w*q2.z);
    float y = q1.x*q2.z + q2.x*q1.z + (q1.w*q2.y - q1.y*q2.w);
    float z = q1.x*q2.w + q2.x*q1.w + (q1.y*q2.z - q1.z*q2.y);
    return vec4(w,x,y,z);
}

vec4 quatConj(in vec4 q) { return vec4(q.x, -q.y, -q.z, -q.w); }

vec4 vec4ToQuat(in vec4 p4) // interpret p4=(x,y,z,w) as q=(w,x,y,z)
{ return vec4(p4.w, p4.x, p4.y, p4.z); }

vec4 quatToVec4(in vec4 q) // interpret q=(qw,qx,qy,qz) => p4=(qx,qy,qz,qw)
{ return vec4(q.y,q.z,q.w,q.x); }

// rotate p-> qL * p * conj(qR)
vec4 rotate4D_Lie(in vec4 p4, in vec4 qL, in vec4 qR)
{
    vec4 qp = vec4ToQuat(p4);
    vec4 qRc= quatConj(qR);
    vec4 t1= quatMul(qL, qp);
    vec4 outQ= quatMul(t1, qRc);
    return quatToVec4(outQ);
}

//----------------------------------------------
// Build spin(4) quaternions
//----------------------------------------------
vec4 buildQuat(float t, float phase)
{
    float angle=0.12*t + phase;
    float halfv=0.5*angle;
    // axis
    vec3 ax=normalize(vec3(sin(0.1*t), cos(0.2*t), sin(0.1*t+phase)));
    float w=cos(halfv);
    float s=sin(halfv);
    return vec4(w, s*ax.x, s*ax.y, s*ax.z);
}

void getSpin4(in float t, out vec4 qL, out vec4 qR)
{
    qL=buildQuat(t,0.0);
    qR=buildQuat(t,1.57);
}

//----------------------------------------------
// Inverse Stereographic R^3->S^3
//----------------------------------------------
vec4 invStereo(vec3 p)
{
    float r2=dot(p,p);
    float denom=r2+1.0;
    denom= max(denom, 1e-9);
    float x=2.0*p.x/denom;
    float y=2.0*p.y/denom;
    float z=2.0*p.z/denom;
    float w=(r2-1.0)/denom;
    return vec4(x,y,z,w);
}

//----------------------------------------------
// 4D Menger membership
//----------------------------------------------
bool inMenger4D(vec4 p4)
{
    vec4 z=p4;
    const int N=6;
    for(int i=0; i<N; i++)
    {
        z*=3.0;
        z=mod(z+1.0,2.0)-1.0;
        if(max(abs(z.x), max(abs(z.y), max(abs(z.z), abs(z.w))))<0.5)
            return false;
    }
    return true;
}

// membership => +1 or -1
float fractalVal(in vec3 p3, float time, vec4 qL, vec4 qR)
{
    vec4 p4= invStereo(p3);
    p4= rotate4D_Lie(p4,qL,qR);
    bool inside= inMenger4D(p4);
    return inside? 1.0 : -1.0;
}

//----------------------------------------------
// Normal estimate w/ finite difference
//----------------------------------------------
vec3 estimateNormal(in vec3 p3, float eps, float time, vec4 qL, vec4 qR)
{
    float c= fractalVal(p3,time,qL,qR);
    float cx= fractalVal(p3+vec3(eps,0,0),time,qL,qR);
    float cy= fractalVal(p3+vec3(0,eps,0),time,qL,qR);
    float cz= fractalVal(p3+vec3(0,0,eps),time,qL,qR);
    return normalize(vec3(cx-c, cy-c, cz-c));
}

//----------------------------------------------
// Sky
//----------------------------------------------
vec3 skyColor(vec3 d)
{
    float u=0.5*(d.y+1.0);
    return mix(vec3(0.7,0.8,1.0), vec3(0.3,0.4,0.7), u);
}

//----------------------------------------------
// Raymarch w/ Binary Refinement
//----------------------------------------------
struct MarchResult {
    bool hit;
    float t;
};

MarchResult marchFractal(in vec3 ro, in vec3 rd, float time, vec4 qL, vec4 qR)
{
    MarchResult mr;
    mr.hit= false;
    mr.t= 0.0;

    float stepSz=0.03;    // can be larger now that we refine
    float tMax=10.0;
    int maxSteps= 333;

    float oldVal= fractalVal(ro, time, qL, qR); // outside or inside at t=0
    for(int i=1; i<maxSteps; i++)
    {
        float t= float(i)*stepSz;
        if(t> tMax) break;

        vec3 pos= ro + t*rd;
        float val= fractalVal(pos, time, qL, qR);

        // check sign flip => surface crossing in [t-stepSz, t]
        if(oldVal<=0.0 && val>0.0)
        {
            // refine in [t-stepSz, t]
            float t0= t-stepSz;
            float t1= t;
            // do a small # of binary steps
            for(int j=0;j<5;j++)
            {
                float tm= 0.5*(t0+t1);
                vec3 pMid= ro + tm*rd;
                float vMid= fractalVal(pMid,time,qL,qR);
                if(vMid>0.0)
                {
                    t1= tm;
                }
                else
                {
                    t0= tm;
                }
            }
            mr.hit= true;
            mr.t= 0.5*(t0+t1);
            return mr;
        }
        oldVal= val;
    }

    // no intersection
    return mr;
}

//----------------------------------------------
// Single-sample rendering
//----------------------------------------------
vec4 renderScene(vec2 fragCoord)
{
    // camera
    vec2 uv= (fragCoord - 0.5*iResolution.xy)/ iResolution.y;
    vec3 camPos= vec3(0,0,3);
    vec3 camTarget= vec3(0);
    vec3 camDir= normalize(camTarget-camPos);
    vec3 camRight= normalize(cross(vec3(0,1,0), camDir));
    vec3 camUp= cross(camDir,camRight);

    vec3 rd= normalize(camDir + uv.x*camRight + uv.y*camUp);

    // build spin(4)
    vec4 qL,qR;
    getSpin4(iTime,qL,qR);

    // march
    MarchResult mr= marchFractal(camPos, rd, iTime, qL,qR);
    if(!mr.hit)
    {
        return vec4(skyColor(rd),1.0);
    }

    // refine position
    vec3 hitPos= camPos + mr.t*rd;

    // normal
    vec3 N= estimateNormal(hitPos, 0.001, iTime, qL,qR);

    // reflection
    vec3 R= reflect(-rd,N);
    vec3 col= skyColor(R);

    return vec4(col,1.0);
}

//----------------------------------------------
// mainImage: optional 2×2 multi-sample
//----------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // 2×2 subpixel offsets
    vec2 px= fragCoord;
    vec2 o[4]= vec2[](
        vec2(-0.25,-0.25),
        vec2( 0.25,-0.25),
        vec2(-0.25, 0.25),
        vec2( 0.25, 0.25)
    );
    vec4 col= vec4(0.0);
    for(int i=0;i<4;i++)
    {
        col+= renderScene(px+o[i]);
    }
    col*=0.25;
    fragColor= col;
}
